class ListInstancesRequest:
    """Заглушка protobuf-сообщения: поля как у настоящего ListInstancesRequest."""

    def __init__(self, folder_id=None, page_size=None, page_token=None, **kwargs):
        self.folder_id = folder_id
        self.page_size = page_size
        self.page_token = page_token
        self.kwargs = kwargs
